/**
 * Political figures directory (reference data, not news).
 *
 * Every office and start date was re-checked on VERIFIED_AS_OF against current reporting from
 * reputable outlets and Wikipedia's current-officeholder lists. Leadership changes often: when
 * the news mentions a change, update the record and its date here.
 *
 * Portraits: each record names its English Wikipedia article (`wiki`). The server looks up that
 * article's lead photo on Wikimedia Commons, keeps it only if its license is public domain or
 * Creative Commons, and shows the author and license next to it (see /api/figures/portraits).
 */

export const VERIFIED_AS_OF = "2026-11-27";

export type FigureRole =
  | "head_of_state"
  | "head_of_government"
  | "head_of_state_and_government"
  | "monarch"
  | "foreign_minister"
  | "minister"
  | "deputy"
  | "opposition"
  | "org_leader"
  | "party_leader"
  | "business_leader";

export interface Figure {
  id: string;
  name: string;
  /** ISO3 country id, or null for international organizations. */
  country: string | null;
  organization?: string;
  position: string;
  role: FigureRole;
  affiliation: string | null;
  inOfficeSince: string; // YYYY-MM-DD
  /** The start date is only known to the year (shown as "since 2019"). */
  approxSince?: boolean;
  /** English Wikipedia article title, used to find a licensed portrait. Defaults to the name. */
  wiki?: string;
  bio: string;
  policies: string[];
  relevance: string;
  verifiedAsOf: string;
  /** Shown when a scheduled event (e.g. an election) may have changed the office since verification. */
  watch?: string;
  portrait?: { url: string; credit: string; license: string; source?: string };
}

const V = VERIFIED_AS_OF;
const f = (x: Omit<Figure, "verifiedAsOf"> & { verifiedAsOf?: string }): Figure => ({ verifiedAsOf: V, ...x });

